//源表：weapon.xlsx（武器表）
#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, weapon> weaponData;
        public weapon GetweaponConfig(int key)
        {
            return ConfigBinary.Require(weaponData, key, "weapon");
        }
        private void LoadweaponConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("weapon"))
            {
                int count = r.ReadInt32();
                weaponData = new Dictionary<int, weapon>(count);
                for (int i = 0; i < count; i++)
                {
                    weapon row;
                    row.key = r.ReadInt32();
                    row.name = ConfigBinary.ReadString(r);
                    row.animType = ConfigBinary.ReadEnum<EntityAnim.CharcterAnimType>(r);
                    row.weaponDisplay = ConfigBinary.ReadEnum<EntityAnim.WeaponDisplayType>(r);
                    weaponData.Add(row.key, row);
                }
            }
        }
    }
    public struct weapon
    {
        public int key;  // 主键
        public string name;  // 名字
        public EntityAnim.CharcterAnimType animType;  // 武器动画类型：0：长枪；1：刀
        public EntityAnim.WeaponDisplayType weaponDisplay;  // 武器显示类型：0：长枪；1：刀；2：双刀
    }
}
